using System.IO;
using System.Text.Json;
namespace Workbench;
public sealed class OperationLink { public string Name { get; set; } = "New item"; public string Description { get; set; } = "Description"; public string Url { get; set; } = "https://"; public bool Enabled { get; set; } = true; public int SortOrder { get; set; } }
public static class OperationsStore { static readonly string FilePath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Toolbox","operations.json"); public static List<OperationLink> Load(){try{if(File.Exists(FilePath))return JsonSerializer.Deserialize<List<OperationLink>>(File.ReadAllText(FilePath))??Defaults();}catch{}return Defaults();} public static void Save(IEnumerable<OperationLink> items){Directory.CreateDirectory(Path.GetDirectoryName(FilePath)!);File.WriteAllText(FilePath,JsonSerializer.Serialize(items,new JsonSerializerOptions{WriteIndented=true}));} static List<OperationLink> Defaults()=>new(){new(){Name="人人都是产品经理",Description="产品、运营与增长内容社区",Url="https://www.woshipm.com",SortOrder=10},new(){Name="运营派",Description="运营案例、方法与实战经验",Url="https://www.yunyingpai.com",SortOrder=20},new(){Name="创业邦",Description="创业与商业创新资讯",Url="https://www.cyzone.cn",SortOrder=30},new(){Name="36氪",Description="商业与科技创新内容",Url="https://36kr.com",SortOrder=40}};}